// lob_gen_commands: writes a v1 command file generated by a testkit workload
// profile (test-only tool; used for the seeded golden file and crash tests).
//
//   lob_gen_commands --profile NAME --seed S --commands N > FILE

#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>

#include "lob/io/text_format.hpp"
#include "lob/testkit/reference_engine.hpp"
#include "lob/testkit/workload.hpp"

int main(int argc, char** argv) {
  std::string profile_name = "mixed";
  std::uint64_t seed = 1;
  std::size_t n = 1'000;
  for (int i = 1; i + 1 < argc; i += 2) {
    const std::string flag = argv[i];
    if (flag == "--profile") {
      profile_name = argv[i + 1];
    } else if (flag == "--seed") {
      seed = std::stoull(argv[i + 1]);
    } else if (flag == "--commands") {
      n = std::stoull(argv[i + 1]);
    } else {
      std::fprintf(stderr, "usage: lob_gen_commands --profile NAME --seed S --commands N\n");
      return 2;
    }
  }
  const lob::testkit::WorkloadProfile* profile = lob::testkit::find_profile(profile_name);
  if (profile == nullptr) {
    std::fprintf(stderr, "unknown profile %s\n", profile_name.c_str());
    return 2;
  }
  lob::testkit::ReferenceEngine model{profile->config};
  lob::testkit::WorkloadGenerator generator{*profile, seed};
  std::vector<lob::io::SequencedCommand> commands;
  for (std::size_t i = 0; i < n; ++i) {
    const lob::Command c = generator.next(static_cast<long>(i), model);
    model.process(c);
    commands.push_back(lob::io::SequencedCommand{.cmd_seq = i + 1, .command = lob::testkit::text_representable(c)});
  }
  const std::string text = lob::io::format_command_file(profile->config, commands);
  std::fwrite(text.data(), 1, text.size(), stdout);
  return 0;
}
